let trailPrevious=null,particleClock=0,frameCount=0,eye=[12,6,-20],target=[0,0,0],menuAngle=0,viewFov=59,last=performance.now(),accumulator=0;
function worldMesh(){if(!worldCache.has(currentMap.id))worldCache.set(currentMap.id,renderer.mesh(E.location(currentMap)));return worldCache.get(currentMap.id)}
