function showState(){if(state!=='garage')setTuningExpanded(false);const running=state==='running',inGame=running||state==='paused';$('menu').hidden=state!=='menu';$('garage').hidden=state!=='garage';$('hud').hidden=!inGame;$('pause').hidden=!running;$('navGarage').hidden=inGame;$('navMaps').hidden=inGame;document.body.dataset.screen=state;$('touch').hidden=!running||!(matchMedia('(any-pointer: coarse)').matches||navigator.maxTouchPoints>0);$('pauseModal').hidden=state!=='paused';$('resultModal').hidden=state!=='result';renderMenu();if(state==='garage')renderGarage();}
