function start(isTrial=false,id=profile.selected){props=B.create(currentMap);trial=isTrial;runCarId=id;runConfig=JSON.parse(JSON.stringify(configuration(id)));runStats=C.stats(id,runConfig);runId=profile.nextRun++;runSettled=false;save();race=null;resetCar();race=isRoad()?R.create(currentMap,car):null;renderer.update(gateMesh,race?E.checkpoint(currentMap,0):new E.Geometry());score=0;distance=0;time=trial?45:isRoad()?currentMap.timeLimit:90;skids.length=0;particles.length=0;renderer.update(skidMesh,new E.Geometry());hitCooldown=0;camMode=0;$('camera').dataset.mode='0';$('camera').setAttribute('aria-label','Камера за машиной. Сменить камеру');$('camera').title='Камера за машиной · сменить';state='running';accumulator=0;showState();updateHud();miniMap();notify(trial?'Тест-драйв · 45 секунд · без наград':isRoad()?'Следуй дороге и проезжай зелёные отметки':'Разгонись → поворот + короткий ручник');}
