$('start').onclick=()=>start();$('pause').onclick=pause;$('resume').onclick=resume;$('restart').onclick=()=>start(trial,runCarId);$('endRun').onclick=()=>finish(false);$('again').onclick=()=>start(trial,runCarId);$('resultExit').onclick=menu;$('resultGarage').onclick=()=>{openGarage();viewingId=runCarId;renderGarage()};
