 $('tuningPanel').dataset.tab=tuningTab;$('tabUpgrade').classList.toggle('active',tuningTab==='upgrade');$('tabStyle').classList.toggle('active',tuningTab==='style');$('upgradePanel').hidden=tuningTab!=='upgrade';$('stylePanel').hidden=tuningTab!=='style';
 $('upgradePanel').innerHTML=Object.entries(C.upgrades).map(([key,u])=>{const level=cfg[key],price=C.upgradePrice(c.id,key,level);return `<div class="upgradeitem"><div class="upgradetitle"><span>${u.name}</span><span class="leveldots" aria-label="Уровень ${level} из 3">${[1,2,3].map(i=>`<i class="${level>=i?'on':''}"></i>`).join('')}</span></div><p>${u.text}</p><button data-upgrade="${key}" ${!owned||level>=3||profile.credits<price?'disabled':''}><span>${level>=3?'МАКСИМУМ':!owned?'Сначала купи авто':'Уровень '+(level+1)}</span><b>${level>=3?'✓':'₵ '+fmt(price)}</b></button></div>`}).join('');
 const names={acid:'Лайм',orange:'Оранжевый',ice:'Лёд',purple:'Фиолетовый',red:'Красный',cyan:'Бирюзовый',cream:'Песочный',black:'Графит',blue:'Синий',pink:'Розовый',green:'Зелёный',silver:'Серебряный'};
