$('tabUpgrade').onclick=()=>{tuningTab='upgrade';renderGarage();$('tuningPanel').scrollTop=0;$('tuningScroll').scrollTop=0};$('tabStyle').onclick=()=>{tuningTab='style';renderGarage();$('tuningPanel').scrollTop=0;$('tuningScroll').scrollTop=0};
let tuningExpanded=false;function setTuningExpanded(on){tuningExpanded=on;$('garage').classList.toggle('tuningExpanded',on);$('expandTuning').setAttribute('aria-expanded',String(on));$('expandTuning').setAttribute('aria-label',on?'Обычный просмотр гаража':'Увеличить просмотр машины и тюнинга');$('expandTuning').title=on?'Обычный просмотр гаража':'Увеличить просмотр машины и тюнинга'}
