$('resetRotation').onclick=()=>previewYaw=-.45;
$('rotateLeft').onclick=()=>previewYaw-=Math.PI/4;$('rotateRight').onclick=()=>previewYaw+=Math.PI/4;
let dragX=null;$('turntable').addEventListener('pointerdown',e=>{dragX=e.clientX;$('turntable').setPointerCapture(e.pointerId)});$('turntable').addEventListener('pointermove',e=>{if(dragX===null)return;previewYaw+=(e.clientX-dragX)*.012;dragX=e.clientX});for(const name of['pointerup','pointercancel','lostpointercapture'])$('turntable').addEventListener(name,()=>dragX=null);
function drawMap(ctx,map,w=180,h=180,player=null){ctx.clearRect(0,0,w,h);const scale=Math.min((w-18)/(map.extent.x*2),(h-18)/(map.extent.z*2)),mx=x=>w/2+x*scale,mz=z=>h/2+z*scale;ctx.strokeStyle='#adc2ad66';ctx.lineWidth=1;ctx.strokeRect(mx(-map.extent.x),mz(-map.extent.z),map.extent.x*2*scale,map.extent.z*2*scale);if(map.road){ctx.strokeStyle='#d5ddc1';ctx.lineWidth=Math.max(2,map.road.width*scale);ctx.beginPath();map.road.points.forEach((p,i)=>i?ctx.lineTo(mx(p.x),mz(p.z)):ctx.moveTo(mx(p.x),mz(p.z)));ctx.stroke();if(player&&race){const gate=map.checkpoints[race.next];if(gate){ctx.fillStyle='#d6ff40';ctx.beginPath();ctx.arc(mx(gate.x),mz(gate.z),4,0,Math.PI*2);ctx.fill()}}}ctx.fillStyle='#b8d66366';for(const z of map.zones)ctx.fillRect(mx(z.x-z.r*.83),mz(z.z-z.r*.83),z.r*1.66*scale,z.r*1.66*scale);ctx.fillStyle='#b5c5b17a';for(const o of map.obstacles)ctx.fillRect(mx(o.x-o.w/2),mz(o.z-o.d/2),o.w*scale,o.d*scale);if(player){ctx.save();ctx.translate(mx(player.x),mz(player.z));ctx.rotate(-player.yaw);ctx.fillStyle='#d6ff40';ctx.beginPath();ctx.moveTo(0,7);ctx.lineTo(-4,-4);ctx.lineTo(4,-4);ctx.closePath();ctx.fill();ctx.restore()}}
function openMaps(){if(state==='running'||state==='paused')return;$('mapsModal').hidden=false;$('mapList').innerHTML=C.maps.map(m=>`<button class="mapitem ${m.id===currentMap.id?'active':''}" data-map="${m.id}"><canvas id="map-preview-${m.id}" width="140" height="140" aria-label="Схема карты ${m.name}"></canvas><div><span class="eyebrow">${m.tag}</span><span class="mapkind">${m.kind==='race'?(m.road.width<12?'Гонка · узкая дорога':'Гонка · широкая дорога'):'Дрифт · свободная площадка'}</span><h3>${m.name}</h3><p>${m.desc}</p></div></button>`).join('');for(const m of C.maps)drawMap($('map-preview-'+m.id).getContext('2d'),m,140,140)}
